        assert!(!refused);
        let tree = success(Route::Tree, &context, function, usize::MAX, None);
        let legacy = success(Route::LegacyArena, &context, function, usize::MAX, None);
        let paid = success(Route::SelectedArena, &context, function, usize::MAX, None);
